class Solution { bool palindrome(string& text,int left,int right){while(left<right)if(text[left++]!=text[right--])return false;return true;}bool check(string& first,string& second){int left=0,right=first.size()-1;while(left<right&&first[left]==second[right]){++left;--right;}return palindrome(first,left,right)||palindrome(second,left,right);}public:bool checkPalindromeFormation(string a,string b){return check(a,b)||check(b,a);} };
